import{_ as o,a0 as e,w as r,s as u,ao as a,I as n,x as i,a1 as s,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Orbital Apps：新一代 Linux 程序 | LCTT x X-CMD","titleTemplate":false,"description":"Orbital Apps：新一代 Linux 程序 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Orbital Apps：新一代 Linux 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Orbital Apps：新一代 Linux 程序 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180508 Orbital Apps - A New Generation Of Linux applications","title":"Orbital Apps：新一代 Linux 程序","tag":"201806","desc":""},"relativePath":"201806/20180508 Orbital Apps - A New Generation Of Linux applications.md","filePath":"[post].md"}'),d={name:"201806/20180508 Orbital Apps - A New Generation Of Linux applications.md"};function b(g,t,w,f,x,m){const l=e("Link");return r(),u("div",null,[t[21]||(t[21]=a('<h1 id="orbital-apps-新一代-linux-程序" tabindex="-1">Orbital Apps：新一代 Linux 程序 <a class="header-anchor" href="#orbital-apps-新一代-linux-程序" aria-label="Permalink to “Orbital Apps：新一代 Linux 程序”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/05/orbital-apps-720x340.jpg" alt=""></p><p>今天，我們要了解 <strong>Orbital Apps</strong> 或 <strong>ORB</strong>（<strong>O</strong>pen <strong>R</strong>unnable <strong>B</strong>undle）<strong>apps</strong>（開放可運行程序包），一個自由的、跨平台的開源程序集合。所有 ORB 程序都是可移動的。你可以將它們安裝在你的 Linux 系統或 USB 驅動器上，以便你可以在任何系統上使用相同的程序。它們不需要 root 權限，並且沒有依賴關係。所有必需的依賴關係都包含在程序中。只需將 ORB 程序複製到 USB 驅動器並將其插入到任何 Linux 系統中就立即開始使用它們。所有設置和配置以及程序的數據都將存儲在 USB 驅動器上。由於不需要在本地驅動器上安裝程序，我們可以在聯機或脱機的計算機上運行應用程序。這意味着我們不需要 Internet 來下載任何依賴。</p><p>ORB 程序壓縮了 60％，因此我們甚至可以從小型 USB 驅動器存儲和使用它們。所有 ORB 應用程序都使用 PGP / RSA 進行簽名，並通過 TLS 1.2 進行分發。所有應用程序打包時都不做任何修改，甚至不會重新編譯。以下是當前可用的便攜式 ORB 應用程序列表。</p><ul><li>abiword</li><li>audacious</li><li>audacity</li><li>darktable</li><li>deluge</li><li>filezilla</li><li>firefox</li><li>gimp</li><li>gnome-mplayer</li><li>hexchat</li><li>inkscape</li><li>isomaster</li><li>kodi</li><li>libreoffice</li><li>qbittorrent</li><li>sound-juicer</li><li>thunderbird</li><li>tomahawk</li><li>uget</li><li>vlc</li><li>未來還有更多</li></ul><p>Orb 是開源的，所以如果你是開發人員，歡迎協作並添加更多程序。</p><h3 id="下載並使用可移動-orb-程序" tabindex="-1">下載並使用可移動 ORB 程序 <a class="header-anchor" href="#下載並使用可移動-orb-程序" aria-label="Permalink to “下載並使用可移動 ORB 程序”">​</a></h3><p>正如我已經提到的，我們不需要安裝可移動 ORB 程序。但是，ORB 團隊強烈建議你使用 <strong>ORB 啓動器</strong> 來獲得更好的體驗。 ORB 啓動器是一個小的安裝程序（小於 5MB），它可幫助你啓動 ORB 程序，並獲得更好，更流暢的體驗。</p>',8)),n("p",null,[t[1]||(t[1]=i("讓我們先安裝 ORB 啓動器。為此，",-1)),s(l,{href:"https://www.orbital-apps.com/documentation/orb-launcher-all-installers"},{default:p(()=>[...t[0]||(t[0]=[i("下載 ORB 啓動器",-1)])]),_:1}),t[2]||(t[2]=i("。你可以手動下載 ORB 啓動器的 ISO 並將其掛載到文件管理器上。或者在終端中運行以下任一命令來安裝它：",-1))]),t[22]||(t[22]=a('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget -O - https://www.orbital-apps.com/orb.sh | bash</span></span></code></pre></div><p>如果你沒有 wget，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl https://www.orbital-apps.com/orb.sh | bash</span></span></code></pre></div><p>詢問時輸入 root 用户和密碼。</p><p>就是這樣。Orbit 啓動器已安裝並可以使用。</p>',5)),n("p",null,[t[4]||(t[4]=i("現在，進入 ",-1)),s(l,{href:"https://www.orbital-apps.com/download/portable_apps_linux/"},{default:p(()=>[...t[3]||(t[3]=[i("ORB 可移動程序下載頁面",-1)])]),_:1}),t[5]||(t[5]=i("，並下載你選擇的程序。在本教程中，我會下載 Firefox。",-1))]),t[23]||(t[23]=a('<p>下載完後，進入下載位置並雙擊 ORB 程序來啓動它。點擊 Yes 確認。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/orbital-apps-1-2.png" alt=""></p><p>Firefox ORB 程序能用了！</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/orbital-apps-2.png" alt=""></p><p>同樣，你可以立即下載並運行任何程序。</p><p>如果你不想使用 ORB 啓動器，請將下載的 <code>.orb</code> 安裝程序設置為可執行文件，然後雙擊它進行安裝。不過，建議使用 ORB 啓動器，它可讓你在使用 ORB 程序時更輕鬆、更順暢。</p><p>就我測試的 ORB 程序而言，它們打開即可使用。希望這篇文章有幫助。今天就是這些。祝你有美好的一天！</p><p>乾杯！！</p><hr>',9)),n("p",null,[t[7]||(t[7]=i("via: ",-1)),s(l,{href:"https://www.ostechnix.com/orbitalapps-new-generation-ubuntu-linux-applications/"},{default:p(()=>[...t[6]||(t[6]=[i("https://www.ostechnix.com/orbitalapps-new-generation-ubuntu-linux-applications/",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=i("作者：",-1)),s(l,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>[...t[8]||(t[8]=[i("SK",-1)])]),_:1}),t[13]||(t[13]=i(" 選題：",-1)),s(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[9]||(t[9]=[i("lujun9972",-1)])]),_:1}),t[14]||(t[14]=i(" 譯者：",-1)),s(l,{href:"https://github.com/geekpi"},{default:p(()=>[...t[10]||(t[10]=[i("geekpi",-1)])]),_:1}),t[15]||(t[15]=i(" 校對：",-1)),s(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=i("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原創編譯，",-1)),s(l,{href:"https://linux.cn/"},{default:p(()=>[...t[17]||(t[17]=[i("Linux中國",-1)])]),_:1}),t[20]||(t[20]=i(" 榮譽推出",-1))])])}const B=o(d,[["render",b]]);export{T as __pageData,B as default};
